Definition putA_post (sp gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi rd cbp E src b : Z) (es : list mbe) (insz n : Z) (bs ej : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists y0 y1 y2 a3x a4x a5x a6x a7x y3 y4 y5 y6 m' (spa1 ff1 fp1 spa2 ff2 fp2 : Z) (gap1 gap2 : list cell) (j0 j24 h80 k0 k32 k64 h72 p7 j40 rj2 : list byte),
    ms' = MS (mkR (Z_to_bv 64 P_A_DBP_RET) (Z_to_bv 64 spa2) gp tp y0 y1 y2 (Z_to_bv 64 spa1) (Z_to_bv 64 spa2) (Z_to_bv 64 (ff2 + 32)) (Z_to_bv 64 b) (Z_to_bv 64 n)
                  a3x a4x a5x a6x a7x (Z_to_bv 64 ff2) (Z_to_bv 64 (Z.shiftr (ff1 + 32) 3 + 2147450880)) (Z_to_bv 64 (ff1 + 32)) (Z_to_bv 64 2147450880)
                  (Z_to_bv 64 (Z.shiftr (ff1 + 32 + 8) 3 + 2147450880)) (Z_to_bv 64 b) (Z_to_bv 64 (ff1 + 32 + 8)) (Z_to_bv 64 (ff2 + 32))
                  (Z_to_bv 64 (Z.shiftr ff2 3 + 2147450880)) (Z_to_bv 64 ff2) y3 y4 y5 y6)
             F (Z_to_bv 64 P_A_MB_PREPARE) fc None m' (seg_rom asegs)
    /\ munch (putA_W lo sp ff1 fp1 ff2 fp2) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ (spa1 = bv_unsigned sp + -160 \/ spa1 = bv_unsigned sp + -176) /\ spa1 mod 32 = 0
    /\ (spa2 = spa1 + -192 \/ spa2 = spa1 + -208) /\ spa2 mod 32 = 0
    /\ fresh_frame H LF 1 ff1 fp1 /\ fresh_frame H ((1, ff1, fp1) :: LF) 1 ff2 fp2
    /\ as_RFS H ((1, ff2, fp2) :: (1, ff1, fp1) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi /\ stk asegs m' lo spa2
    /\ (exists mq, as_RFS H ((1, ff1, fp1) :: LF) mq)
    /\ putA_frames m' sp spa1 ff1 fp1 spa2 ff2 fp2 rd cbp E s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra gap1 gap2 j0 j24 h80 k0 k32 k64 h72
    /\ rw_cells asegs m' (ff1 + 32) [C1 (b8 0); CB 7 p7; CB 40 j40] /\ rw_cells asegs m' (ff2 + 32) [CB 40 rj2]
    /\ rw_cells asegs m' rd [C8 (wz b)] /\ rw_cells asegs m' cbp [C8 (wz src); C8 (wz n)] /\ rw_cells asegs m' E [CB 24 ej] /\ bytes_at asegs m' src bs
    /\ accessible m' rd 8 /\ accessible m' E 24 /\ accessible m' src n /\ accessible m' (ff1 + 32) 48 /\ accessible m' (ff2 + 32) 40
    /\ AMBraw m' b es (mb_out b es insz) insz (mb_outpos es insz) (mb_outpos es insz).
