Lemma putA : forall (ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (LF : list fframe) (LB : list block) (s : as_St H)
    (lo shi rd cbp E src b : Z) (es : list mbe) (insz n : Z) (bs ej : list byte),
  stk asegs m lo (bv_unsigned sp) -> lo + PUT_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp mod 16 = 0 ->
  mem_inv asegs m -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m -> as_RFS H LF m -> (length LF + 1 < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  AMBuf m b es insz -> as_RHEAP H s LB m -> aobj LB LF b 64 -> AMBufOwn LB es -> 1 <= n -> insz + n <= 2^26 ->
  rw_cells asegs m rd [C8 (wz b)] -> aobj LB LF rd 8 -> rd mod 8 = 0 -> accessible m rd 8 ->
  rw_cells asegs m cbp [C8 (wz src); C8 (wz n)] -> bv_unsigned sp <= cbp -> cbp + 16 <= shi -> cbp mod 8 = 0 ->
  rw_cells asegs m E [CB 24 ej] -> aobj LB LF E 24 -> accessible m E 24 ->
  bytes_at asegs m src bs -> zlength bs = n -> aobj LB LF src n -> accessible m src n ->
  evt asegs (putA_post sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra F fc LF lo shi rd cbp E src b es insz n bs ej m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 rd) (Z_to_bv 64 cbp) (Z_to_bv 64 E) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_READER_PUT) fc None m (seg_rom asegs)).
