Definition putB_W (lo spa1 E b : Z) (es : list mbe) (insz n x ff1 fp1 ff2 fp2 : Z) : list (Z * Z) :=
  [(lo, spa1 + 64); (E, E + 24); (b + 24, b + 64);
   (fst (mb_b1 b es insz n x), fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x));
   (fst (mb_b2 b es insz n x), fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x));
   (ff1, ff1 + 128); (sh ff1, sh ff1 + 16); (fp1, fp1 + 1); (ff2, ff2 + 128); (sh ff2, sh ff2 + 16); (fp2, fp2 + 1)]%Z.

Definition putB_post (ra sp gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi spa1 ff1 fp1 ff2 fp2 rd cbp E src b : Z) (es : list mbe) (insz n x : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (putB_W lo spa1 E b es insz n x ff1 fp1 ff2 fp2) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp) /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
    /\ AMBuf m' b (mb_put_es es insz n x) (insz + n)
    /\ rw_cells asegs m' rd [C8 (wz b)] /\ rw_cells asegs m' E (ErrCodeCells EC_clear) /\ rw_cells asegs m' cbp [C8 (wz src); C8 (wz n)]
    /\ bytes_at asegs m' src bs /\ accessible m' E 24 /\ accessible m' src n.
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma putB : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word)
    (m m0 mq0 mq1 : mem) (LF : list fframe) (LB : list block) (s_ : as_St H)
    (lo shi spa1 ff1 fp1 spa2 ff2 fp2 rd cbp E src b : Z) (es : list mbe) (insz n x : Z) (bs : list byte)
    (gap1 gap2 : list cell) (j0 j24 h80 k0 k32 k64 h72 p7 j40 ej : list byte),
  (pcv = Z_to_bv 64 P_A_DBP_RET \/ pcv = ret_pc (Z_to_bv 64 P_A_DBP_RET)) ->
  (spa1 = bv_unsigned sp + -160 \/ spa1 = bv_unsigned sp + -176) -> spa1 mod 32 = 0 ->
  (spa2 = spa1 + -192 \/ spa2 = spa1 + -208) -> spa2 mod 32 = 0 ->
  fresh_frame H LF 1 ff1 fp1 -> fresh_frame H ((1, ff1, fp1) :: LF) 1 ff2 fp2 ->
  as_RFS H ((1, ff2, fp2) :: (1, ff1, fp1) :: LF) m -> as_RFS H LF mq0 -> as_RFS H ((1, ff1, fp1) :: LF) mq1 ->
  ACONST m -> stack0 m lo shi -> stk asegs m lo spa2 -> mem_inv asegs m ->
  lo + PUT_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp <= shi -> bv_unsigned ra mod 2 = 0 ->
  putA_frames m sp spa1 ff1 fp1 spa2 ff2 fp2 rd cbp E s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra gap1 gap2 j0 j24 h80 k0 k32 k64 h72 ->
  rw_cells asegs m (ff1 + 32) [C1 (b8 0); CB 7 p7; CB 40 j40] ->
  rw_cells asegs m (ff2 + 32) (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n)) ->
  rw_cells asegs m rd [C8 (wz b)] -> rd mod 8 = 0 -> accessible m rd 8 -> aapp rd 8 -> (rd + 8 <= E \/ E + 24 <= rd) -> mb_off b (mb_put_es es insz n x) rd 8 ->
  rw_cells asegs m cbp [C8 (wz src); C8 (wz n)] -> bv_unsigned sp <= cbp -> cbp + 16 <= shi -> cbp mod 8 = 0 ->
  rw_cells asegs m E [CB 24 ej] -> E mod 8 = 0 -> accessible m E 24 -> shvis m E (E + 24) -> aapp E 24 -> mb_off b (mb_put_es es insz n x) E 24 ->
  bytes_at asegs m src bs -> zlength bs = n -> accessible m src n -> shvis m src (src + n) -> aapp src n -> (src + n <= E \/ E + 24 <= src) ->
  mb_off b (mb_put_es es insz n x) src n ->
  accessible m (ff1 + 32) 48 -> shvis m (ff1 + 32) (ff1 + 32 + 48) -> accessible m (ff2 + 32) 40 -> shvis m (ff2 + 32) (ff2 + 72) ->
  AMBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^26 -> shvis m b (b + 64) ->
  shvis m (fst (mb_b1 b es insz n x)) (fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x)) ->
  shvis m (fst (mb_b2 b es insz n x)) (fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x)) ->
  (forall x' s', In (x', s') (mb_put_es es insz n x) -> x' + mb_block_size s' + 16 <= as_FSB H \/ as_FSB H + AFS_SIZE <= x' - 16) ->
  as_RHEAP H s_ LB m0 -> aobj LB LF b 64 -> aobj LB LF rd 8 -> aobj LB LF E 24 -> aobj LB LF src n -> AMBufOwn LB (mb_put_es es insz n x) ->
  evt asegs (putB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF lo shi spa1 ff1 fp1 ff2 fp2 rd cbp E src b es insz n x bs m)
    (MS (mkR (Z_to_bv 64 P_A_DBP_RET) (Z_to_bv 64 spa2) gp tp t0 t1 t2 (Z_to_bv 64 spa1) (Z_to_bv 64 spa2) a0 a1 a2 a3 a4 a5 a6 a7
